import{z as l,x as s,o as e,c as p,q as t,j as o,D as E,d as r,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"图形化检测设备","description":"","frontmatter":{"title":"图形化检测设备","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/patterning-inspection-tools.md","filePath":"litho/patterning-inspection-tools.md","lastUpdated":1791063341000}'),B={name:"litho/patterning-inspection-tools.md"};function h(d,a,D,c,C,_){const i=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="图形化检测设备" tabindex="-1">图形化检测设备 <a class="header-anchor" href="#图形化检测设备" aria-label="Permalink to &quot;图形化检测设备&quot;">​</a></h1><div class="epigraph"><p>扫描仪写出潜像，刻蚀留下边；能不能出货取决于谁看见缺陷、谁量 CD、谁量套刻。检测与量测是不同的合同，公开舞台上 KLA 一类把几类工具拆开卖。</p><footer>—— 对照公开的晶圆检测 / 量测工具类别：缺陷检测、电子束审查、CD-SEM、套刻与散射测量</footer></div><p><a href="/litho/resist-vendors">上一课</a>点名胶厂。缺口是：胶的缺陷和 CD 并不由胶厂的桶来裁决，而由晶圆厂的检测与量测机台。本课钉图形化相关工具类别及公开分工，不写国产机的片/小时，也不把份额表发明出来。<a href="/litho/cd-sem-scatterometry">CD-SEM 与散射测量</a>、<a href="/litho/overlay-marks">套刻标记</a>已经讲过物理量；这里补的是设备角色，不是再推一次边缘算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>图形化良率有两类问题：随机或系统缺陷（颗粒、桥、缺孔、残胶），以及合格边上的 CD / overlay 飘。前者要<strong>检测</strong>（inspection）：尽快在整片或抽样场上找到异常。后者要<strong>量测</strong>（metrology）：在专用垫或热点上给出数字去控剂量和网格。口语「KLA 一下」把两类吞并，采购和瓶颈会写错。</p><p><span class="marginnote">检测回答「哪里不一样」，量测回答「具体是多少」。类比安检：检测是 X 光机扫全身找可疑物，量测是抽人量体温给一个精确数字。前者要快和全，后者要准和稳——两类机器因此长得完全不同，买错就是把安检机当体温计用。</span></p><p>公开分工大致是：宽带等离子体或激光扫描做亮场/暗场缺陷检测；电子束做审查与部分高速检测；CD-SEM 看局部形貌和 LER；光学套刻（成像或衍射）向量化位移；散射测量给周期垫的平均剖面。ASML YieldStar 把套刻与散射测量放在计量产品线；Hitachi High-Tech 等以 CD-SEM 公开；应用材料 SEMVision 一类做电子束审查。名单是角色，不是排行。</p><h3 id="检测灵敏度不是分辨率" tabindex="-1">检测灵敏度不是分辨率 \\(k_1\\) <a class="header-anchor" href="#检测灵敏度不是分辨率" aria-label="Permalink to &quot;检测灵敏度不是分辨率 $k_1$&quot;">​</a></h3><p>光学检测的波长和光斑服务于发现异常，不必印器件节距。电子束检测更接近器件尺度，更慢。把检测机写成「又一台光刻机」，会去比 NA。</p><p><span class="marginnote">掩模厂的检验（掩模厂流程课）和晶圆检测不是同一台合同。Lasertec 等在 EUV 掩模检验上的公开角色，不要和晶圆宽带等离子体混名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按层设抽样：显影后检测抓涂胶与曝光缺陷，刻蚀后抓转印缺陷。热点审查用电子束。APC：OCD 或 SEM 抽样喂剂量，套刻计量喂网格。工具配方（色、偏振、算法阈值）与胶、膜堆绑定，换胶等于换检测食谱——上一课的供应商切换会打到这里。</p><p>不要用未公开的国产检测 wph 去规划产能。公开可写的是类别是否存在、成熟制程是否已有国内光学检测产品；吞吐数字缺出处就留空。</p><p><span class="marginnote">抽样率的直觉：整片全检一台机器每片要几分钟到几十分钟，几万片规模的产线养不起每层全检，所以按层风险设抽样——敏感层多抽、成熟层抽一成。抽样是产能税与漏检风险的折中，不是「检得越勤越好」。</span></p>',14)),(e(),o(A,null,{default:E(()=>[n(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E5%85%89%E5%AD%A6%E7%BC%BA%E9%99%B7%E6%A3%80%E6%B5%8B%22%5D%20--%3E%20REV%5B%22%E7%94%B5%E5%AD%90%E6%9D%9F%E5%AE%A1%E6%9F%A5%22%5D%0A%20%20CD%5B%22CD-SEM%22%5D%20--%3E%20APC%5B%22%E5%89%82%E9%87%8F%20%2F%20%E5%BD%A2%E8%B2%8C%E5%8F%8D%E9%A6%88%22%5D%0A%20%20OCD%5B%22%E6%95%A3%E5%B0%84%E6%B5%8B%E9%87%8F%22%5D%20--%3E%20APC%0A%20%20OL%5B%22%E5%A5%97%E5%88%BB%E8%AE%A1%E9%87%8F%22%5D%20--%3E%20GRID%5B%22%E7%BD%91%E6%A0%BC%E5%8F%8D%E9%A6%88%22%5D%0A%20%20INS%20--%3E%20YIELD%5B%22%E5%9B%BE%E5%BD%A2%E5%8C%96%E8%89%AF%E7%8E%87%22%5D%0A%20%20APC%20--%3E%20YIELD%0A%20%20GRID%20--%3E%20YIELD%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="与扫描机内传感器的边界" tabindex="-1">与扫描机内传感器的边界 <a class="header-anchor" href="#与扫描机内传感器的边界" aria-label="Permalink to &quot;与扫描机内传感器的边界&quot;">​</a></h3><p>扫描机内有对准、调平、剂量计，那是曝光控制。KLA 一类通常是独立计量岛或离线岛，抽片更密、算法更重。YieldStar 可以靠近产线，仍是计量产品，不是第二套投影物镜。本课不把 ORION 写成缺陷检测。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学检测把异常写成相对裸片或相对晶粒的差；灵敏度与噪声、膜层对比有关，会漏掉与背景同色的缺陷，也会把薄膜噪声报成缺陷。电子束以分辨率换速度。量测把物理量接到控制环：平均 CD 稳态，套刻吃热与对准残差。两类机制合起来才构成「图形化是否可出货」，扫描仪 wph 只保证潜像写得完。</p><p>EUV 缺孔的尾部必须电子束或电学，光学平均不到泊松。检测策略要按前面<a href="/litho/contact-hole-patterning">接触孔与通孔图形化</a>一课的孔层统计来，而不是按金属线栅的颗粒检测来。</p><p><span class="marginnote">为什么 EUV 孔层必须换工具：光学对几十纳米缺孔的信号已弱到接近随机噪声——缺陷本来就按泊松统计零星出现，「平均看不到」不等于「没有」。这时只能靠电子束逐点看或电学通路测试兜底，否则尾部缺陷直接流进量产。</span></p><p><span class="marginnote">「图形化检测」不含探针电测与终测。那些是另一条良率链，缺陷检测只是前段代理。</span></p>',7)),(e(),o(A,null,{default:E(()=>[n(i,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E6%95%B4%E7%89%87%E6%89%BE%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20OPT%5B%22%E5%85%89%E5%AD%A6%E6%A3%80%E6%B5%8B%3A%20%E5%BF%AB%2C%20%E5%85%A8%E8%A6%86%E7%9B%96%22%5D%0A%20%20TASK%20--%3E%20EB%5B%22%E7%94%B5%E5%AD%90%E6%9D%9F%3A%20%E6%85%A2%2C%20%E5%99%A8%E4%BB%B6%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20OPT%20--%3E%20CATCH%5B%22%E6%8A%93%E5%A4%A7%E5%A4%9A%E6%95%B0%E9%A2%97%E7%B2%92%2F%E6%A1%A5%E8%BF%9E%22%5D%0A%20%20OPT%20--%3E%20MISS%5B%22%E6%BC%8F%E8%83%8C%E6%99%AF%E5%90%8C%E8%89%B2%E7%BC%BA%E9%99%B7%22%5D%0A%20%20EB%20--%3E%20REV%5B%22%E5%A4%8D%E5%AE%A1%E5%85%89%E5%AD%A6%E6%80%80%E7%96%91%E7%82%B9%22%5D%0A%20%20EB%20--%3E%20HOLE%5B%22EUV%20%E7%BC%BA%E5%AD%94%E5%B0%BE%E9%83%A8%22%5D%0A%20%20CATCH%20--%3E%20PLAN%5B%22%E5%88%86%E5%B1%82%E7%BC%BA%E9%99%B7%E6%8D%95%E8%8E%B7%E8%AE%A1%E5%88%92%22%5D%0A%20%20MISS%20--%3E%20PLAN%0A%20%20REV%20--%3E%20PLAN%0A%20%20HOLE%20--%3E%20PLAN%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>禁止编造中科飞测、精测等国产工具的吞吐或灵敏度规格。可以承认公开新闻里存在成熟制程检测产品，数字一律不造。本课不重写胶化学，不重写掩模厂 STARlight。附录文献对照单列在主干之外，不插入这条主干的工具清单。</p><p><span class="marginnote">出处：KLA、ASML YieldStar、Hitachi CD-SEM、电子束审查等公开产品类别说明；晶圆检测与量测的产线分工。不使用无出处的国产 wph。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>检测找缺陷，量测给 CD/overlay 数字，合同不同。</li><li>公开角色：光学检测、电子束审查、CD-SEM、套刻、OCD；KLA 等按类别出现。</li><li>换胶换膜等于换检测食谱。</li><li>不写无出处的国产工具吞吐。</li><li>制程、封装与管制课程到此；下一课转入集成、控制与良率，从等离子体基础起笔。文献附录另开。</li><li>出处：各厂公开工具类别；不编造份额与 wph。</li></ul>',5))])}const T=l(B,[["render",h]]);export{S as __pageData,T as default};
